package cn.mop.api;
import cn.mop.domain.DomainException;
import cn.mop.domain.sla.SlaComplianceScenario;
import cn.mop.domain.sla.SlaComplianceScenario.*;
import java.time.Instant;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
/** Synthetic frozen input comparisons, never approved tenant SLA or compensation evidence. */
class SlaComplianceScenarioTest {
    static final Instant DUE=Instant.parse("2026-10-03T00:00:00Z");
    static final Reference SNAPSHOT=new Reference("SYNTHETIC-SLA-SNAPSHOT",1),APPROVAL=new Reference("SYNTHETIC-MANAGER-EXCLUSION",2);
    static Evidence row(String id,Instant response,Instant recovery){return new Evidence(id,Priority.P1,Exclusion.NONE,null,SNAPSHOT,DUE,DUE,response,recovery);}
    @Test void exactDeadlinesAreInclusiveAndEitherLateDimensionFails(){assertEquals(Outcome.MET,SlaComplianceScenario.evaluate(row("equal",DUE,DUE)).outcome());assertEquals(Outcome.MET,SlaComplianceScenario.evaluate(row("early",DUE.minusMillis(1),DUE.minusMillis(1))).outcome());for(Evidence value:List.of(row("response",DUE.plusMillis(1),DUE),row("recovery",DUE,DUE.plusMillis(1))))assertEquals(Outcome.NOT_MET,SlaComplianceScenario.evaluate(value).outcome());}
    @Test void tenExplicitTicketsWithThreeLateHaveExactSevenTenthsWithoutMoney(){List<Evidence> values=new ArrayList<>();for(int i=0;i<10;i++)values.add(row("ticket-"+i,DUE,i<3?DUE.plusSeconds(1):DUE));Aggregate result=SlaComplianceScenario.aggregate(values,true);assertEquals(AggregateStatus.CALCULATED,result.status());assertEquals(10,result.knownApplicable());assertEquals(7,result.met());assertEquals(3,result.notMet());assertEquals(new Fraction(7,10),result.scenarioAchievement());assertNull(result.effectiveAchievement());assertFalse(result.effective());assertNull(result.compensationAmount());assertEquals("CONFIG_PENDING",result.compensationStatus());}
    @Test void missingActualsAndDeadlinesNeverBecomeZeroOrFourHours(){var missing=SlaComplianceScenario.evaluate(new Evidence("missing",Priority.P2,Exclusion.NONE,null,SNAPSHOT,null,DUE,null,null));assertEquals(Outcome.UNRESOLVED,missing.outcome());assertTrue(missing.reasons().containsAll(List.of(Reason.RESPONSE_DUE_MISSING,Reason.RESPONSE_ACTUAL_MISSING,Reason.RECOVERY_ACTUAL_MISSING)));var total=SlaComplianceScenario.aggregate(List.of(missing.evidence()),true);assertNull(total.scenarioAchievement());assertEquals(AggregateReason.TIMING_UNRESOLVED,total.reason());}
    @Test void oneProvenLateDimensionIsAlreadyNotMetEvenWhenOtherActualIsUnknown(){var value=SlaComplianceScenario.evaluate(row("partly-known",DUE.plusMillis(1),null));assertEquals(Check.NOT_MET,value.response());assertEquals(Check.UNKNOWN,value.recovery());assertEquals(Outcome.NOT_MET,value.outcome());assertTrue(value.reasons().contains(Reason.RECOVERY_ACTUAL_MISSING));assertEquals(new Fraction(0,1),SlaComplianceScenario.aggregate(List.of(value.evidence()),true).scenarioAchievement());}
    @Test void missingFrozenSnapshotPreventsComparisonEvenIfTimesArePresent(){var value=new Evidence("no-snapshot",Priority.P1,Exclusion.NONE,null,null,DUE,DUE,DUE,DUE);var result=SlaComplianceScenario.evaluate(value);assertEquals(Outcome.UNRESOLVED,result.outcome());assertEquals(List.of(Reason.SLA_SNAPSHOT_MISSING),result.reasons());assertNull(SlaComplianceScenario.aggregate(List.of(value),true).scenarioAchievement());}
    @Test void unapprovedOrRejectedExclusionCannotRemoveALateTicket(){for(Exclusion exclusion:List.of(Exclusion.PENDING_APPROVAL,Exclusion.REJECTED)){var value=new Evidence(exclusion.name(),Priority.P3,exclusion,APPROVAL,SNAPSHOT,DUE,DUE,DUE,DUE.plusMillis(1));var result=SlaComplianceScenario.evaluate(value);assertEquals(Outcome.NOT_MET,result.outcome());assertTrue(result.applicable());assertFalse(result.exclusionApplied());assertTrue(result.unapprovedExclusionIgnored());assertEquals(new Fraction(0,1),SlaComplianceScenario.aggregate(List.of(value),true).scenarioAchievement());}}
    @Test void approvedExclusionNeedsExplicitEvidenceAndDoesNotMeanMet(){var absent=new Evidence("no-proof",Priority.P1,Exclusion.APPROVED,null,SNAPSHOT,DUE,DUE,DUE,DUE);assertEquals(Reason.APPROVAL_EVIDENCE_MISSING,SlaComplianceScenario.evaluate(absent).reasons().get(0));var excluded=new Evidence("excluded",Priority.P1,Exclusion.APPROVED,APPROVAL,SNAPSHOT,DUE,DUE,DUE,DUE.plusMillis(1));var result=SlaComplianceScenario.evaluate(excluded);assertEquals(Outcome.NOT_APPLICABLE,result.outcome());assertTrue(result.exclusionApplied());assertFalse(result.applicable());var total=SlaComplianceScenario.aggregate(List.of(excluded),true);assertEquals(0,total.met());assertEquals(AggregateStatus.NO_APPLICABLE,total.status());assertNull(total.scenarioAchievement());}
    @Test void p4IsOutsideScopeWhileUnknownPriorityOrExclusionRemainsUnknown(){var p4=new Evidence("p4",Priority.P4,null,null,null,null,null,null,null);assertEquals(Outcome.NOT_APPLICABLE,SlaComplianceScenario.evaluate(p4).outcome());for(Evidence missing:List.of(new Evidence("priority",null,Exclusion.NONE,null,SNAPSHOT,DUE,DUE,DUE,DUE),new Evidence("exclusion",Priority.P1,null,null,SNAPSHOT,DUE,DUE,DUE,DUE),new Evidence("unknown",Priority.P2,Exclusion.UNKNOWN,null,SNAPSHOT,DUE,DUE,DUE,DUE))){assertNull(SlaComplianceScenario.evaluate(missing).applicable());assertEquals(AggregateReason.APPLICABILITY_UNKNOWN,SlaComplianceScenario.aggregate(List.of(missing),true).reason());}}
    @Test void emptyDenominatorAndIncompletePopulationCannotReportZeroOrFullAchievement(){assertEquals(AggregateStatus.NO_APPLICABLE,SlaComplianceScenario.aggregate(List.of(),true).status());assertNull(SlaComplianceScenario.aggregate(List.of(),true).scenarioAchievement());for(Boolean complete:new Boolean[]{null,false}){var result=SlaComplianceScenario.aggregate(List.of(row("one",DUE,DUE)),complete);assertEquals(AggregateReason.POPULATION_NOT_COMPLETE,result.reason());assertNull(result.scenarioAchievement());}}
    @Test void duplicatesAndOversizedCollectionsCannotInflateCounts(){var one=row("one",DUE,DUE);assertThrows(DomainException.class,()->SlaComplianceScenario.aggregate(List.of(one,one),true));assertThrows(DomainException.class,()->SlaComplianceScenario.aggregate(Collections.nCopies(10001,one),true));assertThrows(DomainException.class,()->SlaComplianceScenario.aggregate(null,true));}
    @Test void inputSnapshotIsImmutableAndLaterConfigurationObjectsCannotChangeEarlierResult(){List<Evidence> input=new ArrayList<>(List.of(row("frozen",DUE,DUE)));var earlier=SlaComplianceScenario.aggregate(input,true);input.set(0,new Evidence("frozen",Priority.P1,Exclusion.NONE,null,new Reference("SYNTHETIC-SLA-SNAPSHOT",2),DUE.minusMillis(1),DUE.minusMillis(1),DUE,DUE));var later=SlaComplianceScenario.aggregate(input,true);assertEquals(Outcome.MET,earlier.items().get(0).outcome());assertEquals(1,earlier.items().get(0).evidence().slaSnapshot().version());assertEquals(Outcome.NOT_MET,later.items().get(0).outcome());assertThrows(UnsupportedOperationException.class,()->earlier.items().clear());}
    @Test void precisionIdentityAndFractionBoundsAreTechnicalGuards(){assertThrows(DomainException.class,()->row("bad",DUE.plusNanos(1),DUE));assertThrows(DomainException.class,()->row("",DUE,DUE));assertThrows(DomainException.class,()->new Reference("",1));assertThrows(DomainException.class,()->new Reference("snapshot",0));assertThrows(DomainException.class,()->new Fraction(1,0));assertThrows(DomainException.class,()->new Fraction(2,1));}
    @Test void explicitReferenceLabelsUseUnicodeCodePointsAndRejectHiddenControls(){assertDoesNotThrow(()->new Reference("😀".repeat(160),1));for(String label:List.of("😀".repeat(161),"x\n","\ufeff\u00a0","\ud800"))assertThrows(DomainException.class,()->new Reference(label,1));}

}
